# -*- coding: utf-8 -*-
"""PEQ strand content (LAUNCH ASDAN, Autumn 1). W1 intro + W2-W6 = ComSk1 complete.
Claims census: only ComSk1 named by Binder code (T/651/6412). Year target (Award/
Extended Award/Certificate) lives at hub level, never as a per-lesson bank. L1 core,
E3 floor, L2-stretch language only; zero L2 registration. No pupil names, no video."""

STRAND_KEY = "PEQ"
FOLDER = "PEQ"
LEVEL = "PEQ Level 1 (E3 floor · L2 stretch)"
SUBTITLE = "LAUNCH Pathway · ASDAN Studio · " + LEVEL

def _ilm(center_icon, center_label, badges, col, bottom):
    """Authored illuminator: labelled badges dock onto a central card. Icon+label+colour,
    horizontal labels, no layout transforms (brief §5). col = strand hex."""
    b = badges  # list of (x,y,w,text) already positioned
    cards = ""
    for i,(x,y,w,txt) in enumerate(b):
        cards += (f'<g class="pop" style="animation-delay:{0.3+i*0.7}s">'
                  f'<rect x="{x}" y="{y}" width="{w}" height="26" rx="13" fill="{col}"/>'
                  f'<text x="{x+w/2}" y="{y+17}" text-anchor="middle" font-size="9.5" fill="#fff">{txt}</text></g>')
    links = ('<path class="draw" style="animation-delay:0.6s" d="M160 56 L208 70" stroke="#cbd5e1" stroke-width="3" stroke-linecap="round"/>'
             '<path class="draw" style="animation-delay:1.3s" d="M160 120 L208 118" stroke="#cbd5e1" stroke-width="3" stroke-linecap="round"/>'
             '<path class="draw" style="animation-delay:2.0s" d="M400 56 L352 70" stroke="#cbd5e1" stroke-width="3" stroke-linecap="round"/>'
             '<path class="draw" style="animation-delay:2.7s" d="M400 120 L352 118" stroke="#cbd5e1" stroke-width="3" stroke-linecap="round"/>')
    return (f'<svg viewBox="0 0 560 190" aria-hidden="true">'
            f'<rect x="210" y="34" width="140" height="126" rx="14" fill="#fff" stroke="{col}" stroke-width="4"/>'
            f'<circle cx="280" cy="78" r="24" fill="{col}"/>'
            f'<text x="280" y="88" text-anchor="middle" font-size="20" fill="#fff">{center_icon}</text>'
            f'<text x="280" y="126" text-anchor="middle" font-size="11" fill="{col}">{center_label}</text>'
            f'{cards}{links}'
            f'<text x="280" y="184" text-anchor="middle" font-size="11" fill="{col}">{bottom}</text></svg>')

# standard badge positions (2 left, 2 right)
_POS = [(29,43,134),(36,107,120),(380,43,169),(387,107,155)]
def ilm(center_icon, center_label, four_labels, bottom, col="#8E4F82"):
    badges=[(_POS[i][0],_POS[i][1],_POS[i][2],four_labels[i]) for i in range(4)]
    return _ilm(center_icon, center_label, badges, col, bottom)

def _base(week, title_short, banks, **kw):
    d = dict(
        strand_key=STRAND_KEY, folder=FOLDER, week=week, weeks_total=6,
        filename=f"PEQ_W{week}_{title_short.replace(' ','_').replace('&','and').replace('/','_')}.html",
        title_short=title_short,
        title_full=f"LAUNCH ASDAN · {LEVEL} W{week} · {title_short}",
        tag_lesson=f"ASDAN Studio · Personal Effectiveness · Week {week} of 6",
        subtitle=SUBTITLE,
        sow_strip=f"Progress SoW · LAUNCH ASDAN Aut 1 · 2026–27 · {LEVEL} · Week {week}",
        banks=banks,
        witness={"header": f"LAUNCH ASDAN W{week} · {title_short}"},
    )
    d.update(kw)
    return d

